NAME = 'SloKJV: Slovenian translation of Holy Bible King James Version (1769)'
BOOK = 'Ecclesiastes'

CHAPTERS = {
    1: {
        1: 'Besede Pridigarja, Davidovega sina, kralja v Jeruzalemu.',
        2: '»Ničevost ničevosti,« pravi Pridigar, »ničevost ničevosti; vse je ničevost.«',
        3: 'Kakšno korist ima človek od vsega svojega truda, ki se ga loteva pod soncem?',
        4: 'En rod mineva in drug rod prihaja, toda zemlja ostaja na veke.',
        5: 'Tudi sonce vzhaja in sonce gre dol in hiti k svojemu kraju, kjer vstaja.',
        6: 'Veter gre proti jugu in se obrača k severu, nenehno se vrti naokoli in veter se ponovno vrača, glede na svoje kroge.',
        7: '§ Vse reke tečejo v morje, vendar morje ni polno; na kraj, od koder reke prihajajo, tja se ponovno vrnejo.',
        8: 'Vse stvari so polne truda, človek tega ne more izreči. Oko ni nasičeno z gledanjem niti uho nasičeno s poslušanjem.',
        9: 'Stvar, ki je bila, to je ta, ki bo in to, kar je storjeno, je to, kar bo storjeno, in pod soncem ni nobene nove stvari.',
        10: 'Ali je katerakoli stvar, o čemer bi bilo lahko rečeno: »Glej, to je novo? To je bilo že od starih časov, ki so bili pred nami.«',
        11: 'Ni spominjanja o prejšnjih stvareh niti ne bo kakršnegakoli spominjanja o stvareh, ki pridejo s tistimi, ki bodo prišle potem.',
        12: 'Jaz, Pridigar, sem bil kralj nad Izraelom v Jeruzalemu.',
        13: 'Izročil sem svoje srce, da išče in preiskuje z modrostjo glede vseh stvari, ki so storjene pod nebom. To bolečo muko je Bog izročil človeškim sinovom, da bi bili vežbani s tem.',
        14: 'Videl sem vsa dela, ki so storjena pod soncem in glej, vse je ničevost in draženje duha.',
        15: 'To, kar je skrivljeno, ne more biti izravnano; in to, kar je pomanjkljivo, ne more biti prešteto.',
        16: 'Posvetoval sem se s svojim lastnim srcem, rekoč: »Glej! Prišel sem k velikemu premoženju in prejel sem več modrosti kakor vsi tisti, ki so bili pred menoj v Jeruzalemu. Da, moje srce je imelo sijajno izkušnjo modrosti in spoznanja.',
        17: 'Izročil sem svoje srce, da spoznam modrost in da spoznam norost in neumnost. Zaznal sem, da je tudi to draženje duha.',
        18: 'Kajti v mnogi modrosti je mnogo žalosti in kdor povečuje spoznanje, povečuje bridkost.«',
    },
    2: {
        1: 'V svojem srcu sem rekel: »Pojdi sedaj, preizkusil te bom z veseljem, zato uživaj zadovoljstvo.« Glej, tudi to je ničevost.',
        2: 'O smehu sem rekel: » To je zmešano.« O veselju: »Kaj to počne?«',
        3: 'V svojem srcu sem iskal, da se izročim vinu in vendar sem seznanjal svoje srce z modrostjo in se poprijel neumnosti, dokler ne bi videl, kaj je bilo to dobro za človeške sinove, kar naj bi storili pod nebom vse dni svojega življenja.',
        4: 'Naredil sem si velika dela. Zgradil sem si hiše, si zasadil vinograde,',
        5: 'naredil sem si vrtove in sadovnjake in vanje sem zasadil vse vrste sadnih dreves.',
        6: 'Naredil sem si vodne tolmune, da z njimi namakam gozd, ki rojeva drevesa.',
        7: 'Pridobil sem si služabnike in dekle in imel služabnike rojene v moji hiši. Prav tako sem imel veliko posesti z veliko in malo živine, povrh vsega kar je bilo v Jeruzalemu pred menoj.',
        8: 'Zbral sem si tudi srebro in zlato in izvoljen zaklad od kraljev in od provinc. Dobil sem si pevce in pevke in radosti človeških sinov, kakor glasbene instrumente in to od vseh vrst.',
        9: 'Tako sem bil velik in narasel bolj kakor vsi, ki so bili pred menoj v Jeruzalemu. Tudi moja modrost je ostala z menoj.',
        10: 'Karkoli so si moje oči želele, jim tega nisem preprečil, svojega srca nisem zadržal pred nobeno radostjo, kajti moje srce se je veselilo v vsem mojem trudu in to je bil moj delež vsega mojega truda.',
        11: 'Potem sem pogledal na vsa dela, ki sta jih moji roki izvršili in na trud, ki sem se ga trudil delati. Glej, vse je bilo ničevost in draženje duha in ni bilo koristi pod soncem.',
        12: 'Obrnil sem se, da bi gledal modrost, norost in neumnost, kajti kaj lahko stori človek, ki prihaja za kraljem? Celó to, kar je bilo že narejeno.',
        13: 'Potem sem videl, da modrost prekaša neumnost, kolikor svetloba prekaša temo.',
        14: 'Oči modrega človeka so v njegovi glavi, toda bedak hodi v temi. Zaznal pa sem tudi, da se vsem tem dogaja en dogodek.',
        15: 'Potem sem v svojem srcu rekel: »Kakor se dogaja bedaku, tako se dogaja celo meni in zakaj sem bil potem modrejši?« Nato sem rekel v svojem srcu, da je tudi to ničevost.',
        16: 'Kajti na veke ni spomina na modrega bolj kakor na bedaka. Glede na to, da kar je sedaj, bo v dneh, ki bodo prišli, vse pozabljeno. In kako umira moder človek? Kakor bedak.',
        17: 'Zato sem zasovražil življenje, ker mi je delo, ki je opravljeno pod soncem, mučno, kajti vse je ničevost in draženje duha.',
        18: 'Da, zasovražil sem ves svoj trud, ki sem se ga lotil pod soncem, ker naj bi ga zapustil človeku, ki bo za menoj.',
        19: 'Kdo ve, ali bo moder človek ali bedak? Vendar bo imel oblast nad vsem mojim trudom, v čemer sem se trudil in v čemer sem se pokazal modrega pod soncem. Tudi to je ničevost.',
        20: 'Zato sem odšel naokrog, da svojemu srcu povzročim, da obupuje od vsega truda, ki sem ga prijel pod soncem.',
        21: 'Kajti je človek, čigar trud je v modrosti, v spoznanju in v nepristranskosti, vendar bo človeku, ki se ni trudil s tem, to zapustil za njegov delež. Tudi to je ničevost in veliko zlo.',
        22: 'Kajti kaj ima človek od vsega svojega truda in od draženja svojega srca, v čemer se je trudil pod soncem?',
        23: 'Kajti vsi njegovi dnevi so bridkosti in njegova muka žalost, da, njegovo srce si ponoči ne vzame počitka. Tudi to je ničevost.',
        24: 'Nič ni boljšega za človeka, kakor da naj bi jedel in pil ter da naj bi svojo dušo pripravil uživati dobro v svojem trudu. Tudi to sem videl, da je bilo to iz Božje roke.',
        25: 'Kajti kdo lahko jé ali kdo lahko hiti k temu bolj kakor jaz?',
        26: 'Kajti Bog daje človeku, ki je dober v njegovem pogledu, modrost, spoznanje in radost, toda grešniku daje muko, da zbira in kopiči, da bi lahko dal tistemu, ki je dober pred Bogom. Tudi to je ničevost in draženje duha.',
    },
    3: {
        1: 'Za vsako stvar je obdobje in čas za vsak namen pod nebom:',
        2: 'čas, da si rojen in čas za smrt, čas za sajenje in čas za ruvanje tega, kar je vsajeno,',
        3: 'čas za ubijanje in čas za zdravljenje, čas za rušenje in čas za gradnjo,',
        4: 'čas za jokanje in čas za smejanje, čas za žalovanje in čas za ples,',
        5: 'čas za odmetavanje kamnov in čas za zbiranje kamnov, čas za objemanje in čas za zadržanje pred objemanjem,',
        6: 'čas za pridobivanje in čas za izgubljanje, in čas za hranjenje in čas za odmetavanje,',
        7: 'čas za paranje in čas za šivanje, čas za molčanje in čas za govorjenje,',
        8: 'čas za ljubezen in čas za sovraštvo, čas vojne in čas miru.',
        9: 'Kakšno korist ima kdor dela v tem, v čemer se trudi?',
        10: 'Videl sem muko, ki jo Bog daje človeškim sinovom, da bi bili vežbani v tem.',
        11: '§ Vsako stvar je naredil krasno ob svojem času. Prav tako je v njihovo srce postavil svet, tako da noben človek ne more spoznati dela, ki ga Bog dela od začetka do konca.',
        12: 'Vem, da ni dobrega v njih, temveč za človeka, da se veseli in da v svojem življenju dela dobro.',
        13: 'Prav tako, da naj bi vsak človek jedel, pil in užival dobro od vsega svojega truda, to je darilo od Boga.',
        14: 'Vem, da karkoli Bog dela, bo to za vedno. Nič ne more biti k temu dodano niti karkoli od tega odvzeto. Bog to dela, da naj bi se ljudje bali pred njim.',
        15: 'To, kar je bilo, je sedaj in to, kar naj bi bilo, je že bilo in Bog zahteva to, kar je minilo.',
        16: 'Poleg tega sem pod soncem videl kraj sodbe, da je bila tam zlobnost in kraj pravičnosti, da je bila tam krivičnost.',
        17: 'V svojem srcu sem rekel: ›Bog bo sodil pravičnega in zlobnega, kajti tam je čas za vsak namen in za vsako delo.‹',
        18: 'V svojem srcu sem rekel glede stanja človeških sinov, da bi se jim Bog lahko pokazal in da bi lahko videli, da so oni sami živali.',
        19: 'Kajti to, kar zadene človeške sinove, zadene živali, celo ena stvar jih zadene; kakor umre eden, tako umre drugi, da, vsi imajo en dih, tako da človek nima nobene premoči nad živaljo, kajti vse je ničevost.',
        20: 'Vsi gredo k enemu kraju, vsi so iz prahu in vsi se ponovno spremenijo v prah.',
        21: 'Kdo pozna človekovega duha, ki gre navzgor in duha živali, ki gre navzdol k zemlji?',
        22: 'Zatorej zaznavam, da ni ničesar boljšega, kakor da naj bi se človek veselil v svojih lastnih delih, kajti to je njegov delež, kajti kdo ga bo privedel, da vidi kaj bo za njim?',
    },
    4: {
        1: 'Tako sem se vrnil in preudaril vsa zatiranja, ki so storjena pod soncem in gledal solze tistih, ki so bili zatirani in niso imeli tolažnika in je bila moč na strani njihovih zatiralcev, toda niso imeli nobenega tolažnika.',
        2: 'Zatorej sem bolj hvalil mrtve, ki so že mrtvi, kakor živeče, ki so še živi.',
        3: 'Da, kakor oni oboji je boljši tisti, ki še ni bil, ki še ni videl zlobnega dela, ki je storjeno pod soncem.',
        4: 'Ponovno, preudaril sem vso muko in vsako pravilno delo, da zaradi tega človeku zavidajo njegovi sosedi. Tudi to je ničevost in draženje duha.',
        5: 'Bedak drži prekrižane roke in jé svoje lastno meso.',
        6: 'Boljše je prgišče s spokojnostjo, kakor obe roki napolnjeni z muko in draženjem duha.',
        7: 'Potem sem se vrnil in videl ničevost pod soncem.',
        8: 'Tam je nekdo sam in ni drugega, da, nima niti otroka niti brata, vendar ni konca vsemu njegovemu trudu, niti njegovo oko ni nasičeno z bogastvi, niti ne pravi: »Za koga se trudim in svoji duši kratim dobro?« Tudi to je ničevost, da, to je boleča muka.',
        9: 'Dva sta boljša kakor eden, zato ker imata dobro nagrado za svoj trud.',
        10: 'Kajti če padeta, bo vsak dvignil svojega tovariša; toda gorje tistemu, ki je sam, ko pade, kajti nima drugega, da mu pomaga pokonci.',
        11: 'Ponovno, če dva ležita skupaj, potem imata toploto, toda kako se lahko nekdo ogreje sam?',
        12: 'In če eden zoper njega prevlada, se mu bosta zoperstavila dva in trojna vrvica ni hitro pretrgana.',
        13: 'Boljši je ubog in moder otrok, kakor star in nespameten kralj, ki noče biti več opomnjen.',
        14: 'Kajti on prihaja iz ječe, da vlada, medtem ko tisti, ki je prav tako rojen v njegovem kraljestvu, postaja ubog.',
        15: 'Preudaril sem vse živeče, ki hodijo pod soncem, z drugim otrokom, ki bo vstal namesto njega.',
        16: 'Ni konca vsemu ljudstvu, celó vseh, ki so bili pred njimi. Tudi tisti, ki pridejo potem, se ne bodo veselili v njem. Zagotovo je tudi to ničevost in draženje duha.',
    },
    5: {
        1: 'Varuj svoje stopalo, ko greš k Božji hiši in bodi bolj pripravljen prisluhniti kakor izročiti klavno daritev bedakov, kajti ne preudarjajo, da počnejo zlo.',
        2: 'Ne bodi prenagljen s svojimi usti in tvoje srce naj ne bo hitro, da izreče katerokoli stvar pred Bogom, kajti Bog je v nebesih, ti pa na zemlji, zato naj bo tvojih besed malo.',
        3: 'Kajti sanje prihajajo po množici zadev in bedakov glas je razpoznan z množico besed.',
        4: 'Kadar prisegaš zaobljubo Bogu, ne odlašaj, da jo izpolniš, kajti on nima zadovoljstva v bedakih. Izpolni to, kar si se zaobljubil.',
        5: 'Bolje je to, da ne prisežeš, kakor da prisežeš zaobljubo, pa ne izpolniš.',
        6: '§ Ne dopusti svojim ustom, da bi tvojemu mesu povzročila, da greši niti pred angelom ne povej, da je bila pomota. Zakaj bi bil Bog ob tvojem glasu jezen in bi uničil delo tvojih rok?',
        7: 'Kajti v množici sanj in mnogih besedah so tudi številne ničevosti, toda boj se Boga.',
        8: 'Če vidiš v provinci zatirati ubogega in nasilne prevračati sodbo in pravico, se ne čudi ob zadevi, kajti kdor je višji kakor najvišji, upošteva; in obstaja višji kakor oni.',
        9: 'Poleg tega je donos zemlje za vse; sam kralj je postrežen s poljem.',
        10: 'Kdor ljubi srebro, ne bo potešen s srebrom niti kdor ljubi obilje, z donosom; tudi to je ničevost.',
        11: 'Kadar se dobrine povečujejo, so povečane, da se pojejo; kakšno dobro je njegovim lastnikom, razen da jih gledajo s svojimi očmi?',
        12: 'Spanje delovnega človeka je sladko, bodisi jé malo ali veliko, toda obilje bogastva mu ne bo pustilo spati.',
        13: 'Je boleče zlo, ki sem ga videl pod soncem, namreč bogastva, varovana za njihove lastnike v njihovo škodo.',
        14: 'Toda ta bogastva izginejo po zli zadevi. Zaplodil je sina, pa v njegovi roki ni ničesar.',
        15: 'Kakor je nag prišel iz maternice svoje matere, se bo vrnil kakor je prišel in ničesar ne bo vzel od svojega truda, kar bi v svoji roki lahko odnesel.',
        16: 'Tudi to je boleče zlo, da v vseh točkah, kakor je prišel, bo tako odšel; in kakšno korist ima tisti, ki se je trudil za veter?',
        17: '§ Prav tako vse svoje dni jé v temi in ima mnogo bridkosti in besa s svojo slabostjo.',
        18: 'Glej to, kar sem videl. Dobro in ljubko je za nekoga jesti, piti in uživati dobro od vsega svojega truda, ki se ga loteva pod soncem vse dni svojega življenja, ki mu jih daje Bog, kajti to je njegov delež.',
        19: 'Tudi vsakemu človeku, ki mu Bog daje bogastva in premoženje, mu daje moč, da od tega jé in da vzame svoj delež in se veseli v svojem trudu; to je darilo od Boga.',
        20: 'Kajti dni svojega življenja se ne bo dosti spominjal, ker mu Bog odgovarja v radosti njegovega srca.',
    },
    6: {
        1: 'Je zlo, ki sem ga videl pod soncem in to je pogosto med ljudmi.',
        2: 'Človek, ki mu je Bog dal bogastva, premoženje in čast, tako da za svojo dušo ne potrebuje ničesar od vsega, kar si želi, pa mu vendar Bog ne daje moči, da od tega jé, temveč to jé tujec. To je ničevost in to je zla bolezen.',
        3: 'Če človek zaplodi sto otrok in živi mnogo let, tako da je dni njegovih let mnogo in njegova duša ne bo nasičena z dobrinami in tudi da nima pogreba, pravim, da je prezgodaj rojeni boljši kakor on.',
        4: 'Kajti vstopa z ničevostjo in odhaja v temi in njegovo ime bo prekrito s temo.',
        5: 'Poleg tega ni videl sonca niti ni poznal nobene stvari; ta ima več počitka kakor drugi.',
        6: 'Da, čeprav je bilo rečeno, da živi dvakrat tisoč let, vendar ni videl dobrega; mar ne gredo vsi na en kraj?',
        7: 'Vse človekovo delo je za njegova usta, pa vendar apetit ni potešen.',
        8: 'Kajti kaj ima modri več kakor bedak? Kaj ima ubogi, da zna hoditi pred živečimi?',
        9: 'Boljši je pogled oči kakor tavanje poželenja. Tudi to je ničevost in draženje duha.',
        10: 'To, kar je bilo, je že imenovano in je znano, da je to človek; niti se ne more pričkati s tistim, ki je mogočnejši kakor on.',
        11: 'Ker je tukaj mnogo stvari, ki povečujejo ničevost, kaj je človek boljši?',
        12: 'Kajti kdo ve kaj je boljše za človeka v tem življenju, vse dni njegovega praznega življenja, ki jih preživlja kakor senca? Kajti kdo lahko človeku pove kaj bo za njim pod soncem?',
    },
    7: {
        1: 'Dobro ime je boljše kakor dragoceno mazilo in dan smrti [je boljši] kakor dan rojstva nekoga.',
        2: 'Bolje je iti v hišo žalujočega, kakor iti v hišo pojedine, kajti to je konec vseh ljudi; in živi si bodo to položili k srcu.',
        3: 'Bridkost je boljša kot smeh, kajti z žalostjo obličja je srce postalo boljše.',
        4: 'Srce modrega je v hiši žalovanja, toda srce bedakov je v hiši veselja.',
        5: 'Bolje je poslušati oštevanje modrega, kakor za človeka poslušati pesem bedakov.',
        6: 'Kajti kakor je prasketanje trnja pod loncem, tak je smeh bedaka. Tudi to je ničevost.',
        7: 'Zatiranje modrega zagotovo dela besnega in podkupnina uničuje srce.',
        8: 'Boljši je konec stvari kakor njen začetek, in potrpežljivi v duhu je boljši kakor ponosni v duhu.',
        9: '§ V svojem duhu ne bodi nagel, da bi bil jezen, kajti jeza počiva v naročju bedakov.',
        10: 'Ne reci: »Kaj je razlog, da so bili prejšnji dnevi boljši kakor tile?« Kajti glede tega nisi modro poizvedel.',
        11: 'Modrost je dobra z dediščino; in z njo je korist tistim, ki gledajo sonce.',
        12: 'Kajti modrost je obramba in denar je obramba, toda odličnost spoznanja je, da modrost daje življenje tem, ki jo imajo.',
        13: 'Preudari Gospodovo delo, kajti kdo lahko izravna to, kar je on skrivil?',
        14: 'Na dan uspevanja bodi radosten, toda na dan nadloge preudari; tudi Bog je postavil enega nasproti drugemu, z namenom, da človek ne bi ničesar našel za njim.',
        15: 'Vse stvari sem videl v dneh svoje ničevosti. Je pravičen človek, ki propada v svoji pravičnosti in je zloben človek, ki v svoji zlobnosti podaljšuje svoje življenje.',
        16: 'Ne bodi preko mere pravičen niti se ne delaj preveč modrega. Zakaj bi samega sebe uničil?',
        17: 'Ne bodi preveč zloben niti ne bodi nespameten. Zakaj bi umrl pred svojim časom?',
        18: 'Dobro je, da bi to zgrabil, da, tudi pred tem ne umikaj svoje roke, kajti kdor se boji Boga, bo izmed vseh prišel naprej.',
        19: 'Modrost krepi modrega bolj kakor deset silnih mož, ki so v mestu.',
        20: 'Kajti na zemlji ni pravičnega človeka, ki dela dobro in ne greši.',
        21: 'Prav tako se ne oziraj na vse besede, ki so izgovorjene, da ne bi slišal svojega služabnika [kako] te preklinja,',
        22: 'kajti pogosto tudi tvoje lastno srce ve, da si ti sam podobno preklinjal druge.',
        23: 'Vse to sem preizkusil z modrostjo. Rekel sem: »Moder bom,« toda to je bilo daleč od mene.',
        24: 'To, kar je daleč proč in presegajoče globoko, kdo to lahko spozna?',
        25: 'Svoje srce sem posvetil védenju in preiskovanju in iskanju modrosti in razlogu za stvari in da spoznam zlobnost neumnosti, celo nespametnost in norost.',
        26: 'Našel sem grenkejše kakor smrt, žensko, čigar srce so pasti in mreže in njene roke kakor trakovi. Kdorkoli ugaja Bogu, bo zbežal pred njo, toda grešnik bo vzet po njej.',
        27: '»Glej, to sem našel,« pravi pridigar, naštevajoč enega za drugim, da spozna razlog.',
        28: 'Kar vendar moja duša išče, toda ne najdem. Našel sem enega med tisočimi, toda ženske med vsemi tistimi nisem našel.',
        29: 'Glej, samo to sem našel, da je Bog človeka naredil poštenega, toda oni so iskali mnoge domiselnosti.',
    },
    8: {
        1: 'Kdo je kakor moder človek? In kdo pozna pomen stvari? Človekova modrost pripravi njegov obraz, da zasveti in srčnost njegovega obraza bo spremenjena.',
        2: 'Svetujem ti, da obdržiš kraljevo zapoved in da upoštevaš Božjo prisego.',
        3: 'Ne bodi nagel, da greš izven njegovega pogleda. Ne stoj v zli stvari, kajti on počne karkoli mu ugaja.',
        4: 'Kjer je kraljeva beseda, tam je moč, in kdo mu lahko reče: »Kaj počneš?«',
        5: 'Kdorkoli se drži zapovedi, ne bo čutil nobene zle stvari in srce modrega človeka razlikuje tako čas kakor sodbo.',
        6: 'Ker za vsak namen je čas in sodba, zato je človeška beda velika nad njim.',
        7: 'Kajti on ne ve, tega kar bo, kajti kdo mu lahko pove kdaj bo to?',
        8: 'Nobenega človeka ni, da ima moč nad duhom, da obdrži duha niti nima moči na dan smrti in v tej vojni ni nobene poravnave niti zlobnost ne bo osvobodila tistih, ki so ji izročeni.',
        9: 'Vse to sem videl in svoje srce posvetil vsakemu delu, ki je storjeno pod soncem. Je čas, v katerem en človek vlada nad drugim v svojo lastno škodo.',
        10: 'Tako sem videl zlobne pokopane, ki so prišli in odšli iz kraja svetih in so bili pozabljeni v mestu, kjer so tako počeli. Tudi to je ničevost.',
        11: 'Ker obsodba zoper zlo delo ni izvršena naglo, zato je srce človeških sinov v njih popolnoma naravnano, da počno zlo.',
        12: 'Čeprav grešnik tisočkrat stori zlo in bodo njegovi dnevi podaljšani, vendar zagotovo vem, da bo dobro s tistimi, ki se bojijo Boga, ki se bojijo pred njim,',
        13: 'toda z zlobnim ne bo dobro niti ne bo podaljšal svojih dni, ki so kakor senca, ker se pred Bogom ne boji.',
        14: 'Je ničevost, ki je storjena na zemlji; da so pravični ljudje, ki se jim dogaja glede na delo zlobnih; ponovno, so zlobni ljudje, ki se jim dogaja glede na delo pravičnih. Rekel sem, da je tudi to ničevost.',
        15: 'Potem sem priporočal veselje, ker človek pod soncem nima boljše stvari, kot da jé in da pije in da je vesel, kajti to bo ostalo z njim od njegovega truda [vse] dni njegovega življenja, ki mu ga Bog daje pod soncem.',
        16: 'Ko sem usmeril svoje srce, da spoznam modrost in da vidim opravilo, ki je storjeno na zemlji (kajti tam je ta, ki niti podnevi niti ponoči s svojimi očmi ne vidi spanja),',
        17: 'sem potem zagledal vsa Božja dela, da človek ne more spoznati dela, ki je storjeno pod soncem. Ker čeprav se človek trudi to spoznati, vendar tega ne bo našel. Da, nadalje, čeprav moder človek misli, da to pozna, vendar tega ne bo zmožen najti.',
    },
    9: {
        1: 'Kajti vse to sem preudaril v svojem srcu, celo da vse to oznanim, da so pravični in modri in njihova dela v roki Boga. Noben človek ne spozna bodisi ljubezni ali sovraštva po vsem, kar je pred njimi.',
        2: 'Vse stvari pridejo podobno k vsem: je en dogodek pravičnemu in zlobnemu; dobremu, čistemu in nečistemu; tistemu, ki daruje in tistemu, ki ne daruje; kakor je dobri, tako je grešnik; in kdor prisega, kakor tisti, ki se prisege boji.',
        3: 'To je zlo med vsemi stvarmi, ki so storjene pod soncem, da je en dogodek za vse. Da, tudi srce človeških sinov je polno zla in dokler živijo je v njihovih srcih norost, potem pa gredo k smrti.',
        4: 'Kajti za tistega, ki je pridružen k vsem živim, je upanje, kajti živ pes je boljši kakor mrtev lev.',
        5: 'Kajti živi vedo, da bodo umrli, toda mrtvi ne vedo ničesar niti nimajo več nobene nagrade, kajti spomin nanje je pozabljen.',
        6: 'Prav tako je njihova ljubezen, njihovo sovraštvo in njihova zavist sedaj izginila niti nimajo več deleža na veke v katerikoli stvari, ki je storjena pod soncem.',
        7: 'Pojdi svojo pot, svoj kruh jej z radostjo in svoje vino pij z veselim srcem, kajti Bog sedaj sprejema tvoja dela.',
        8: 'Naj bodo tvoje obleke vedno bele in tvoji glavi naj ne manjka mazila.',
        9: 'Živi radostno, z ženo, ki jo ljubiš, vse dni življenja svoje ničevosti, ki ti je dana pod soncem vse dni tvoje ničevosti, kajti to je tvoj delež v tem življenju in v tvojem trudu, ki se ga lotevaš pod soncem.',
        10: 'Karkoli tvoja roka najde, da stori, to stôri z vso svojo močjo, kajti v grobu, kamor greš, ni dela, niti naklepa, niti spoznanja, niti modrosti.',
        11: 'Vrnil sem se in videl pod soncem, da tek ni za nagle, niti bitka za močne, niti kruh za modre, niti bogastva za ljudi spoznanja, niti celo naklonjenost veščim ljudem, temveč se čas in priložnost dogajata njim vsem.',
        12: 'Kajti tudi človek ne pozna svojega časa. Kakor ribe, ki so ujete v zlo mrežo in kakor ptice, ki so ujete v zanko, tako so človeški sinovi ujeti v zlobnem času, ko le-ta nenadoma pade nanje.',
        13: 'Tudi to modrost sem videl pod soncem in ta se mi je zdela velika:',
        14: 'bilo je majhno mesto in znotraj njega malo ljudi in zoper njega je prišel velik kralj, ga oblegal in zoper njega zgradil velike branike.',
        15: 'Torej v njem je bil najden reven, moder človek in on je s svojo modrostjo osvobodil mesto, vendar se noben človek ni spominjal tega ubogega moža.',
        16: 'Potem sem rekel: »Modrost je boljša kakor moč; kljub temu je modrost revnega moža prezirana in njegove besede niso slišane.«',
        17: 'Besede modrih ljudi se bolj slišijo v tišini kakor vpitje tistega, ki vlada med bedaki.',
        18: 'Modrost je boljša kakor bojna orožja, toda en grešnik uničuje mnogo dobrega.',
    },
    10: {
        1: 'Mrtve muhe lekarnarjevemu mazilu povzročijo, da od sebe širi smrdljiv vonj; tako je majhna neumnost tistemu, ki ima sloves zaradi modrosti in časti.',
        2: 'Srce modrega človeka je pri njegovi desnici, toda bedakovo srce pri njegovi levici.',
        3: 'Da, tudi kadar kdor je bedak, hodi po poti, ga njegova modrost izneverja in vsakemu govori, da je bedak.',
        4: 'Če vladarjev duh vstane zoper tebe, ne zapusti svojega mesta, kajti ustrežljivost pomirja velike prestopke.',
        5: 'Je zlo, ki sem ga videl pod soncem, kakor pomota, ki izvira od vladarja:',
        6: 'neumnost je postavljena na visoko dostojanstvo, bogati pa sedijo na nizkem kraju.',
        7: 'Videl sem služabnike na konjih, prince pa hoditi kakor služabniki po tleh.',
        8: 'Kdor koplje jamo, bo padel vanjo, kdorkoli pa lomi ograjo, ga bo pičila kača.',
        9: 'Kdorkoli odstranja kamne, bo z njimi poškodovan in kdor cepi drva, bo s tem izpostavljen nevarnosti.',
        10: 'Če je železo topo in ne nabrusi ostrine, potem mora vložiti več moči; toda modrost je koristna, da usmerja.',
        11: 'Zagotovo bo kača pičila brez izrekanja uroka in blebetavec ni boljši.',
        12: 'Besede iz ust modrega moža so milostljive, toda ustnice bedaka bodo samega sebe pogoltnile.',
        13: 'Začetek besed iz njegovih ust je nespametnost, konec njegovega govora pa je pogubna norost.',
        14: 'Tudi bedak je poln besed. Človek ne more povedati kaj bo, in kaj bo za njim, kdo mu lahko pove?',
        15: 'Trud nespametnih izčrpava vsakogar izmed njih, ker ne ve kako iti do mesta.',
        16: 'Gorje tebi, oh dežela, kadar je tvoj kralj otrok in tvoji princi jedo zjutraj!',
        17: 'Blagoslovljena si ti, oh dežela, kadar je tvoj kralj sin plemičev in tvoji princi jedo v pravšnjem obdobju, za moč in ne za pijanost!',
        18: 'Z veliko lenobe zgradba propada in zaradi brezdelja rok kaplja skozi hišo.',
        19: 'Praznovanje je narejeno za smeh in vino dela vesele, toda denar odgovarja vsem stvarem.',
        20: 'Ne preklinjaj kralja niti v svojih mislih in ne preklinjaj bogatega v svoji spalnici, kajti zračna ptica bo odnesla glas in kar ima peruti, bo povedalo zadevo.',
    },
    11: {
        1: 'Svoj kruh vrzi na vode, kajti našel ga boš po mnogih dneh.',
        2: 'Daj delež sedmim in tudi osmemu, kajti ne veš kakšno zlo bo na zemlji.',
        3: 'Če so oblaki polni dežja, se izlijejo na zemljo, in če drevo pade proti jugu ali proti severu, na kraj, kamor drevo pade, tam bo.',
        4: 'Kdor opazuje veter, ne bo sejal in kdor se ozira na oblake, ne bo žel.',
        5: 'Kakor ne veš kakšna je pot duha niti kako rastejo kosti v maternici tiste, ki je z otrokom; tako ne poznaš del Boga, ki dela vse.',
        6: 'Zjutraj sej svoje seme in zvečer ne zadržuj svoje roke, kajti ne veš, ali bo uspevalo to ali ono, ali pa bosta oba enako dobra.',
        7: 'Resnično, svetloba je prijazna in prijetna stvar je za oči, da gledajo sonce,',
        8: 'toda če človek živi mnogo let in se veseli v njih vseh, naj se vendar spomni dni teme, kajti mnogo jih bo. Vse, kar prihaja, je ničevost.',
        9: 'Razveseli se, oh mladenič, v svoji mladosti in naj te tvoje srce spodbuja v dneh tvoje mladosti in hodi po poteh svojega srca in za pogledom svojih oči; toda vedi, da te bo Bog zaradi vseh teh stvari privedel v obsodbo.',
        10: 'Zatorej od svojega srca odstrani bridkost in odloži zlo od svojega mesa, kajti otroštvo in mladost sta ničevost.',
    },
    12: {
        1: 'Spomni se torej svojega Stvarnika v dneh svoje mladosti, ko niso prišli zli dnevi niti se niso približala leta, ko boš rekel: »V njih nimam veselja,«',
        2: 'dokler sonce ali svetloba ali luna ali zvezde ne bodo otemnele niti se oblaki vrnili za dežjem,',
        3: 'na dan, ko bodo čuvaji hiše trepetali in se bodo močni možje sklonili in mlinarji odnehajo, ker jih je malo in tisti, ki gledajo skozi okna, postanejo zatemnjeni',
        4: 'in bodo vrata po ulicah zaprta, ko je glas mletja nizek in bo vstal ob ptičjem glasu in bodo ponižane vse hčere petja;',
        5: 'tudi ko jih bo strah tega, kar je visoko in bodo strahovi na poti in bo mandljevec cvetel in bo kobilica breme in bo hrepenenje izneverilo; ker človek odhaja k svojemu dolgemu domu in žalovalci gredo po ulicah,',
        6: 'ali preden se srebrna vrvica odveže ali zlomi zlata skledica ali lončen vrč razbije ob studencu ali zlomi kolo pri vodnem zbiralniku.',
        7: 'Potem se bo prah vrnil k zemlji, kakor je bil; in duh se bo vrnil k Bogu, ki ga je dal.',
        8: '»Ničevost ničevosti,« pravi pridigar, »vse je ničevost.«',
        9: 'In poleg tega, ker je bil pridigar moder, še vedno uči ljudstvo spoznanja. Da, pazil je, poiskal in uredil mnogo pregovorov.',
        10: 'Pridigar je iskal, da odkrije sprejemljive besede in to, kar je bilo napisano, je bilo iskreno, celó besede resnice.',
        11: 'Besede modrih so kakor palice z bodicami in kakor žeblji, pritrjeni s pomočjo gospodarjev zborov, ki so izročeni od enega pastirja.',
        12: 'Nadalje, moj sin, bodi opomnjen s temi. Pisanju mnogih knjig ni konca in mnogo učenja je utrujenost telesu.',
        13: 'Prisluhnimo zaključku celotne zadeve: »Boj se Boga in se drži njegovih zapovedi, kajti to je vsa človekova dolžnost.',
        14: 'Kajti Bog bo vsako delo privedel na sodbo, z vsako skrivno stvarjo, bodisi je ta dobra, bodisi je ta slaba.«',
    },
}
